  readonly price: Price;
  readonly billing_period: BillingPeriod;
  readonly interval_count: IntervalCount;
  readonly plan: Plan;
  readonly new_plan: NewPlan;
  readonly idempotency_key: IdempotencyKey;
  readonly quantity: Quantity;
  readonly trial_days: TrialDays;
  readonly trial_end: TrialEnd;
  readonly subscription_status: SubscriptionStatus;
  readonly current_period_start: CurrentPeriodStart;
  readonly current_period_end: CurrentPeriodEnd;
  readonly proration: Proration;
  readonly resume_on: ResumeOn;
  readonly trial_will_end_sent_at: TrialWillEndSentAt;
  readonly cancel_mode: CancelMode;
  readonly cancel_at: CancelAt;
  readonly subscription: Subscription;
  readonly stored_subscription: StoredSubscription;
  readonly existing_subscription: ExistingSubscription;
  readonly subscriptions: Subscriptions;
  readonly stored_subscriptions: StoredSubscriptions;
  readonly event_id: EventId;
  readonly event_type: EventType;
  readonly occurred_at: OccurredAt;
  readonly event: Event;
  readonly events: Events;
  readonly subscription_change: SubscriptionChange;
  readonly invoice_status: InvoiceStatus;
  readonly line_quantity: LineQuantity;
  readonly amount: Amount;
  readonly line: Line;
  readonly lines: Lines;
  readonly total: Total;
  readonly period_start: PeriodStart;
  readonly period_end: PeriodEnd;
  readonly invoice: Invoice;
  readonly stored_invoice: StoredInvoice;
  readonly invoices: Invoices;
  readonly stored_invoices: StoredInvoices;
  readonly create_request: CreateRequest;
  readonly subscription_lookup: SubscriptionLookup;
  readonly list_request: ListRequest;
  readonly subscription_list: SubscriptionList;
  readonly change_plan_request: ChangePlanRequest;
  readonly pause_request: PauseRequest;
  readonly resume_request: ResumeRequest;
  readonly cancel_request: CancelRequest;
  readonly announce_request: AnnounceRequest;
